@pytest.mark.parametrize('physical',[False,True]) @pytest.mark.parametrize('nucleus',[False,True]) @pytest.mark.parametrize('exclude',[False,True]) @pytest.mark.parametrize('cohort',['empty','self','coincident','all']) def test_scalar_rows_match_independent_nearest_formula(physical,nucleus,exclude,cohort): doc,a,b,c=scene();options=q.SpatialDistanceOptions() options.units=q.SpatialDistanceUnits.MICROMETRES if physical else q.SpatialDistanceUnits.PIXELS options.prefer_nucleus=nucleus;options.exclude_self=exclude targets={'empty':[],'self':[a],'coincident':[c],'all':[c,b,a]}[cohort] request=q.SpatialDistanceRequest(doc,[b,a],targets,options) result=q.measure_spatial_distances(request) assert request.matches(doc) and result.belongs_to(request) assert result.row_count==result.source_count==2 and result.target_count==len(targets) assert result.input_sha256==request.input_sha256 and result.algorithm=='qpx.centroid-nearest/1' assert len(result.sha256)==len(result.input_sha256)==64 points={a:(32,32),b:((35,36) if nucleus else (38,38)),c:(32,32)} sx,sy=(.5,.25) if physical else (1,1) assert (result.x_scale,result.y_scale)==(sx,sy) for row in result.rows(): x,y=points[row.source_id] candidates=[(math.hypot((points[t][0]-x)*sx,(points[t][1]-y)*sy),t) for t in targets if not exclude or t!=row.source_id] assert (row.source_centroid.x,row.source_centroid.y)==(x,y) assert row.source_nucleus==(row.source_id==b and nucleus) if not candidates: assert row.distance is row.target_id is row.target_revision is row.target_centroid is row.target_kind is None else: distance,target=min(candidates) assert row.target_id==target and row.distance==pytest.approx(distance,abs=1e-9,rel=1e-12) assert (row.target_centroid.x,row.target_centroid.y)==points[target] > assert request.provenance.source_only and result.provenance.document_revision==doc.revision ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E AttributeError: 'qupathxx._native.AnalysisProvenance' object has no attribute 'source_only'
